#include <stdio.h>
struct Point { int x; int y; };
int main(void) {
    struct Point p;
    struct Point *ptr = &p;
    ptr->x = 5;
    ptr->y = 10;
    printf("%d\n", ptr->x * ptr->y);
    return 0;
}

