#include <stdio.h>
struct Counter {
    int count;
};
static void inc(struct Counter c) {
    c.count++;
}
int main(void) {
    struct Counter c = {0};
    inc(c);
    printf("%d\n", c.count);
    return 0;
}

#include <stdio.h>
struct Student { int id; int marks; };
int main(void) {
    struct Student s[3] = {{1, 80}, {2, 90}, {3, 70}};
    int total = 0;
    for (int i = 0; i < 3; i++) total += s[i].marks;
    printf("%d\n", total);
    return 0;
}

#include <stdio.h>
struct Point { int x; int y; };
static void move(struct Point *p, int dx, int dy) {
    p->x += dx;
    p->y += dy;
}
int main(void) {
    struct Point p = {1, 2};
    move(&p, 3, 4);
    printf("%d %d\n", p.x, p.y);
    return 0;
}

