#include <stdio.h>
struct Student { int id; int marks; };
int main(void) {
    struct Student s[3] = {{1, 70}, {2, 90}, {3, 80}};
    int best = 0;
    for (int i = 1; i < 3; i++) {
        if (s[i].marks > s[best].marks) best = i;
    }
    printf("%d\n", s[best].id);
    return 0;
}

